        array("id" => "s3e28", "season" => 3, "number" => 28, "name" => "Duel On A Vanishing Planet", "airdate" => "7 Aug 1991", "runtime" => 30, "rating" => 8, "summary" => "Let's Get It On!! Two Remain on a Vanishing PlanetGoku chooses to stay behind and finish his fight with Frieza.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422935.jpg"),
        array("id" => "s3e29", "season" => 3, "number" => 29, "name" => "Pathos Of Frieza", "airdate" => "14 Aug 1991", "runtime" => 30, "rating" => 8, "summary" => "Pathos of Freeza! Once He Starts Shaking He's Unstoppable!!Time grows short for Goku as each passing second brings Namek closer to destruction.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422936.jpg"),
        array("id" => "s3e30", "season" => 3, "number" => 30, "name" => "Frieza Defeated!", "airdate" => "21 Aug 1991", "runtime" => 30, "rating" => 7.3, "summary" => "Goku's Declaration of Victory!! As Freeza Destroys Himself…Frieza lashes out in a blind rage, launching a reckless volley of energy attacks. In the face of Goku's superior power, the evil tyrant's greatest fear has come true.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422938.jpg"),
        array("id" => "s3e31", "season" => 3, "number" => 31, "name" => "Mighty Blast of Rage", "airdate" => "28 Aug 1991", "runtime" => 30, "rating" => 9, "summary" => "Freeza Defeated!! A Single Blast Packed With a Totality of RageLearning that the Namekian Dragon Balls can revive humans many times, Gohan and the others let out a cry of joy. Now they can bring Krillin and Chiaozu back to life. On Namek, Goku's crushing vict…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422941.jpg"),
        array("id" => "s3e32", "season" => 3, "number" => 32, "name" => "Namek's Explosion... Goku's End?", "airdate" => "4 Sep 1991", "runtime" => 30, "rating" => 9, "summary" => "Planet Namek's Great Explosion!! Goku Disappears into SpaceEven though it looks like Goku is trapped on the exploding planet Namek, Dende has a good reason to celebrate: the Dragon Balls have the power to bring Goku back to life.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422948.jpg"),
        array("id" => "s3e33", "season" => 3, "number" => 33, "name" => "Goku's Alive!!", "airdate" => "11 Sep 1991", "runtime" => 30, "rating" => 9, "summary" => "Son Goku Survived — The Z Warriors Are All Resurrected!!It is a time of joyful reunions as old friends long absent are finally wished home with the Dragon Balls! Krillin and Yamcha are brought back from the spirit realm.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422949.jpg"),
    )),
    array("number" => 4, "name" => "Season 4", "rating" => 7.6, "episodes" => array(
        array("id" => "s4e1", "season" => 4, "number" => 1, "name" => "The Heavens Tremble", "airdate" => "18 Sep 1991", "runtime" => 30, "rating" => 7.5, "summary" => "Terrible Happenings in Heaven!! Garlic Jr. Becomes God?!Gohan's going fishing, Krillin's found a girlfriend, and it looks as though peace has once again returned to the Earth.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422950.jpg"),
        array("id" => "s4e2", "season" => 4, "number" => 2, "name" => "Black Fog of Terror", "airdate" => "25 Sep 1991", "runtime" => 30, "rating" => 8, "summary" => "Black Mist of Terror…!! Everyone Turns DemonicGarlic Junior releases the Black Water Mist upon an unsuspecting world. As the dreaded fog spreads, so does Garlic Junior's control over the Earth!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422958.jpg"),
        array("id" => "s4e3", "season" => 4, "number" => 3, "name" => "Battle in Kami's Lookout", "airdate" => "2 Oct 1991", "runtime" => 30, "rating" => 8, "summary" => "The Heavens Become the Battlefield!! Piccolo Becomes Devilish Again…As Piccolo attempts to hold off the Spice Boys and the infected Z Fighters, Gohan and Krillin race toward Kami's Lookout.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422972.jpg"),
        array("id" => "s4e4", "season" => 4, "number" => 4, "name" => "Fight With Piccolo", "airdate" => "9 Oct 1991", "runtime" => 30, "rating" => 8, "summary" => "", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422973.jpg"),
        array("id" => "s4e5", "season" => 4, "number" => 5, "name" => "Call For Restoration", "airdate" => "16 Oct 1991", "runtime" => 30, "rating" => 8.5, "summary" => "Restore Everyone's Minds!! The Ultra Holy Water Resting in the TempleKrillin, after suffering a Spice Boys beating, attempts to free Kami and Mr. Popo, but he soon falls prey to the Black Water Mist.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422976.jpg"),
        array("id" => "s4e6", "season" => 4, "number" => 6, "name" => "Suicidal Course", "airdate" => "23 Oct 1991", "runtime" => 30, "rating" => 8, "summary" => "It Can't Wait Until Morning!! Kami-sama Decides on a Suicidal Course of ActionPiccolo and Krillin spring their trap, revealing that they have pretended to be infected by the Black Water Mist!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422980.jpg"),
        array("id" => "s4e7", "season" => 4, "number" => 7, "name" => "Extreme Measures", "airdate" => "30 Oct 1991", "runtime" => 30, "rating" => 8.5, "summary" => "A Battle of Extreme Measures!! Kami-sama Breaks the CovenantGarlic Junior and his Spice Boys harness the evil power of the Makyo Star to become stronger than ever, but Gohan, Krillin, and Piccolo are ready to battle.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422982.jpg"),
        array("id" => "s4e8", "season" => 4, "number" => 8, "name" => "The World Awakens", "airdate" => "6 Nov 1991", "runtime" => 30, "rating" => 8, "summary" => "The Ultra Holy Water Worked!! The World Awakens From its NightmareIn a last ditch effort to save his friends, Gohan launches an all out assault.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422983.jpg"),
        array("id" => "s4e9", "season" => 4, "number" => 9, "name" => "Brief Chance for Victory", "airdate" => "13 Nov 1991", "runtime" => 30, "rating" => 9, "summary" => "Gohan's Brief Chance for Victory!! Destroy Planet Makyō…Blinded by rage and desperate to destroy his enemies, Garlic Junior uses his power to open up the Dead Zone! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422984.jpg"),
        array("id" => "s4e10", "season" => 4, "number" => 10, "name" => "Krillin's Proposal", "airdate" => "20 Nov 1991", "runtime" => 30, "rating" => 7, "summary" => "You're My Guy… Kuririn — The 101st ProposalKrillin faces his toughest challenge ever: surviving a shopping trip with Maron! And it looks like she's picking out a wedding dress!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1422985.jpg"),
        array("id" => "s4e11", "season" => 4, "number" => 11, "name" => "Frieza's Counterattack", "airdate" => "27 Nov 1991", "runtime" => 30, "rating" => 7, "summary" => "That's Earth, Papa… Freeza and his Father Strike BackGohan's cracking the books, and his new tutor is cracking the whip! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423009.jpg"),
        array("id" => "s4e12", "season" => 4, "number" => 12, "name" => "The Mysterious Youth", "airdate" => "4 Dec 1991", "runtime" => 30, "rating" => 7, "summary" => "I Will Defeat Freeza… The Mysterious Boy Awaiting GokuThe Earth faces its darkest hour as Frieza and his father King Cold rapidly approach! ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423011.jpg"),
        array("id" => "s4e13", "season" => 4, "number" => 13, "name" => "Another Super Saiyan?", "airdate" => "11 Dec 1991", "runtime" => 30, "rating" => 8, "summary" => "Freeza Halved By a Single Blow!! Another Super SaiyanFrieza and King Cold descend upon the Earth, but a mysterious warrior has come to thwart their diabolical plot for revenge.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423013.jpg"),
        array("id" => "s4e14", "season" => 4, "number" => 14, "name" => "Welcome Back Goku", "airdate" => "18 Dec 1991", "runtime" => 30, "rating" => 7.5, "summary" => "Heya!! It's Been a While… Son Goku ReturnsAfter defeating Frieza and King Cold, the mysterious stranger announces the exact time and place of Goku's arrival on Earth.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423014.jpg"),
        array("id" => "s4e15", "season" => 4, "number" => 15, "name" => "Mystery Revealed", "airdate" => "15 Jan 1992", "runtime" => 30, "rating" => 8.5, "summary" => "My Dad is Vegeta… Confessions of the Mysterious BoyAfter testing Goku in combat, the mysterious stranger reveals his true identity!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423016.jpg"),
        array("id" => "s4e16", "season" => 4, "number" => 16, "name" => "Goku's Special Technique", "airdate" => "22 Jan 1992", "runtime" => 30, "rating" => 7.5, "summary" => "Goku's New Finishing Technique?! Watch This, My Instantaneous MovementThe future has been written - or has it? That's what Goku and the rest of the Z-Fighters must decide as they hear Trunks' ominous warning.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423017.jpg"),
        array("id" => "s4e17", "season" => 4, "number" => 17, "name" => "Z Warriors Prepare", "airdate" => "29 Jan 1992", "runtime" => 30, "rating" => 7.5, "summary" => "I Will Overcome… Goku!! The King of the Saiyan Warrior RaceGohan learns some new tricks, Vegeta pushes himself to the breaking point, and Yamcha struggles just to keep up.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423018.jpg"),
        array("id" => "s4e18", "season" => 4, "number" => 18, "name" => "Goku's Ordeal", "airdate" => "5 Feb 1992", "runtime" => 30, "rating" => 7.5, "summary" => "License Mastery? Goku's Newest TrialGoku and Piccolo take a day off from training to enroll in driving school. These two mighty warriors may be the Earth's only chance for survival.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423026.jpg"),
        array("id" => "s4e19", "season" => 4, "number" => 19, "name" => "The Androids Appear", "airdate" => "12 Feb 1992", "runtime" => 30, "rating" => 7, "summary" => "Murderers Who Leave No Trace — Which Ones Are the Artificial Humans?!The Androids are here, and they're wreaking havoc on an unsuspecting city! Goku and his friends must now put their training to the test!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423031.jpg"),
        array("id" => "s4e20", "season" => 4, "number" => 20, "name" => "A Handy Trick", "airdate" => "19 Feb 1992", "runtime" => 30, "rating" => 8, "summary" => "The Cold-Blooded No. 20's Hideous Atrocities!! Goku's Super Transformation of AngerYamcha is held at the mercy of the ruthless No. 20, and Goku and the others must race to help their friend. ", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423055.jpg"),
        array("id" => "s4e21", "season" => 4, "number" => 21, "name" => "Double Trouble for Goku", "airdate" => "26 Feb 1992", "runtime" => 30, "rating" => 7.5, "summary" => "Goku's Double-Shock!! Caught Between Illness and AdversaryThe battle with the Androids begins as Goku launches an all out assault against #19. The Super Saiyan seems to have the fight under control.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423057.jpg"),
        array("id" => "s4e22", "season" => 4, "number" => 22, "name" => "Upgrade to Super Saiyan", "airdate" => "4 Mar 1992", "runtime" => 30, "rating" => 7, "summary" => "The Might of Vegeta!! The Blood of a Super Saiyan AwakensAttacked from within by a crippling virus, Goku is helpless against the maniacal #19. But just when it looks like the end for Goku, Vegeta appears on on the scene.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423058.jpg"),
        array("id" => "s4e23", "season" => 4, "number" => 23, "name" => "The Secret of Doctor Gero", "airdate" => "11 Mar 1992", "runtime" => 30, "rating" => 7, "summary" => "No. 20's Defiant Smile… The Secret of Doctor GeroIn his first fight as a Super Saiyan, Vegeta takes control of the battlefield.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423059.jpg"),
        array("id" => "s4e24", "season" => 4, "number" => 24, "name" => "More Androids?!", "airdate" => "18 Mar 1992", "runtime" => 30, "rating" => 7.5, "summary" => "A Present More Terrifying Than the Future?! Trunks' SuspicionsVegeta, Piccolo, and Gohan lead an exhaustive search through the mountains for #20. But the hunters are also the hunted!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423068.jpg"),
        array("id" => "s4e25", "season" => 4, "number" => 25, "name" => "Follow Dr. Gero", "airdate" => "25 Mar 1992", "runtime" => 30, "rating" => 7, "summary" => "", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423070.jpg"),
