        array("id" => "s4e27", "season" => 4, "number" => 27, "name" => "Goku's Assassin", "airdate" => "8 Apr 1992", "runtime" => 30, "rating" => 7, "summary" => "", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423077.jpg"),
        array("id" => "s4e28", "season" => 4, "number" => 28, "name" => "Deadly Beauty", "airdate" => "15 Apr 1992", "runtime" => 30, "rating" => 7, "summary" => "", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423080.jpg"),
        array("id" => "s4e29", "season" => 4, "number" => 29, "name" => "No Match for the Androids", "airdate" => "22 Apr 1992", "runtime" => 30, "rating" => 7, "summary" => "", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423081.jpg"),
