    array("number" => 5, "name" => "Season 5", "rating" => 8.5, "episodes" => array(
        array("id" => "s5e1", "season" => 5, "number" => 1, "name" => "Seized with Fear", "airdate" => "20 May 1992", "runtime" => 30, "rating" => 8.5, "summary" => "Trunks and Krillin join Bulma at the crash site of the mysterious time capsule and find an eerie clue: the shell of a large, locust-like creature! Whatever arrived in the time capsule isn't human, and it's on the loose!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423094.jpg"),
        array("id" => "s5e2", "season" => 5, "number" => 2, "name" => "The Reunion", "airdate" => "27 May 1992", "runtime" => 30, "rating" => 8.5, "summary" => "An insect-like monster threatens to turn Gingertown into a ghastly graveyard! In response to this new menace, Kami fuses with Piccolo, and the resulting Super Namekian flies to Gingertown for a showdown of epic proportions!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423095.jpg"),
        array("id" => "s5e3", "season" => 5, "number" => 3, "name" => "Borrowed Powers", "airdate" => "3 Jun 1992", "runtime" => 30, "rating" => 8.5, "summary" => "Gingertown becomes a battlefield as Piccolo confronts Cell. This monster from the future gains his strength by sucking the life out of his victims! But that's not the creature's only talent. He also knows the Kamehameha Wave!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423097.jpg"),
        array("id" => "s5e4", "season" => 5, "number" => 4, "name" => "His Name Is Cell", "airdate" => "9 Jun 1992", "runtime" => 30, "rating" => 8.5, "summary" => "A Life Form of Evil and Destruction!! His Name is Artificial Human CellHeavily-armored tanks fail to halt Cell's rampage, and now it's up to Piccolo to stop the monster! As the Namekian fights for survival, Cell reveals that he's actually an android, the ulti…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423760.jpg"),
        array("id" => "s5e5", "season" => 5, "number" => 5, "name" => "Piccolo's Folly", "airdate" => "17 Jun 1992", "runtime" => 30, "rating" => 8.5, "summary" => "Piccolo's Grievous Mistake! Cell Escapes Into the City!Piccolo cleverly distracts Cell long enough to regenerate his arm. The Namekian is ready for another round, and Krillin and Trunks have arrived to provide backup! With the odds mounting against him, Cell…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423761.jpg"),
        array("id" => "s5e6", "season" => 5, "number" => 6, "name" => "Laboratory Basement", "airdate" => "24 Jun 1992", "runtime" => 30, "rating" => 8.5, "summary" => "The Secret of Cell's Birth! What Lies Below the Laboratory?!With hopes of saving the future, Trunks and Krillin race to destroy Dr. Gero's lab. Meanwhile, Piccolo and Tien search for the elusive Cell. But how can they stop an enemy who knows their every move?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423762.jpg"),
        array("id" => "s5e7", "season" => 5, "number" => 7, "name" => "Our Hero Awakes", "airdate" => "1 Jul 1992", "runtime" => 30, "rating" => 8.5, "summary" => "Goku Awakens to Battle! Go Beyond the Super Saiyan!!In South City, Cell plows through more civilians and accidentally runs into Krillin! Goku finally gets back on his feet, but with Cell and the other androids in full stride, can the Saiyan hero still make a…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423763.jpg"),
        array("id" => "s5e8", "season" => 5, "number" => 8, "name" => "Time Chamber", "airdate" => "8 Jul 1992", "runtime" => 30, "rating" => 8.5, "summary" => "Hasten Your Training, Saiyans! In the Room of Spirit and Time…As Cell continues his deadly march, Goku hatches a plan to squeeze a year's worth of training into just one day! Back at Master Roshi's, the android trio arrives looking for Goku! Can Piccolo hold…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423764.jpg"),
        array("id" => "s5e9", "season" => 5, "number" => 9, "name" => "The Monster is Coming", "airdate" => "15 Jul 1992", "runtime" => 30, "rating" => 8, "summary" => "The Gekiretsu Kodan that Split the Heavens!! Piccolo vs Artificial Human No. 17Behind the closed doors of the Hyperbolic Time Chamber, Vegeta and Trunks struggle to push past the level of Super Saiyan! Down on Earth, Piccolo challenges Android 17 to a battle!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423765.jpg"),
        array("id" => "s5e10", "season" => 5, "number" => 10, "name" => "He's Here", "airdate" => "22 Jul 1992", "runtime" => 30, "rating" => 8.5, "summary" => "How I Have Waited For this Day!! Cell's Prologue to PerfectionStronger than ever after fusing with Kami, Piccolo leads the attack against the androids! It looks like the Super Namekian has things under control until Cell arrives on the battlefield! Can anyone…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423766.jpg"),
        array("id" => "s5e11", "season" => 5, "number" => 11, "name" => "Up to Piccolo", "airdate" => "29 Jul 1992", "runtime" => 30, "rating" => 8.5, "summary" => "The Suicidal Counterattack Proves Ineffective! Piccolo's Flame Burns Out!!Just as Cell is about to absorb Android 17, Piccolo bravely steps in and foils the monster's plan! Does the Super Namekian really have a chance at stopping Cell on his own?! Or is he si…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423767.jpg"),
        array("id" => "s5e12", "season" => 5, "number" => 12, "name" => "Silent Warrior", "airdate" => "5 Aug 1992", "runtime" => 30, "rating" => 8.5, "summary" => "One Final Remaining Hope… The Silent Warrior No. 16 Takes Action!!When Android 16 claims to be as strong as Cell, it seems like a wild boast! But after he launches an offensive that throws Cell against the ropes, it becomes clear that the big android has the…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423768.jpg"),
        array("id" => "s5e13", "season" => 5, "number" => 13, "name" => "Say Goodbye, 17", "airdate" => "12 Aug 1992", "runtime" => 30, "rating" => 8.5, "summary" => "No. 17 is Swallowed… The Transforming Cell is a Super GourmetIt's android against android as 16 clashes with Cell. Android 16 is the stronger fighter, but Cell is far too driven to be stopped now! With an underheanded attack, Cell moves one step closer to his…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423769.jpg"),
        array("id" => "s5e14", "season" => 5, "number" => 14, "name" => "Sacrifice", "airdate" => "19 Aug 1992", "runtime" => 30, "rating" => 8.5, "summary" => "Tomorrow I am Going to Pulverize You!! Goku's ChallengeWith an onslaught of psychic blasts, Tien gives Androids 16 and 18 a chance to escape, but the powerful attack rapidly drains his strength. Tien may have saved the androids, but can he save himself?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423770.jpg"),
        array("id" => "s5e15", "season" => 5, "number" => 15, "name" => "Saiyans Emerge", "airdate" => "26 Aug 1992", "runtime" => 30, "rating" => 8.5, "summary" => "I'll Finish Everything!! A Reborn Vegeta, Father and Son, Sally ForthTrunks and Vegeta emerge from the time chamber after a year of intense training. Goku and Gohan are next into the room, but with Cell nearing his ultimate form, can the fighters afford to wa…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423771.jpg"),
        array("id" => "s5e16", "season" => 5, "number" => 16, "name" => "Super Vegeta", "airdate" => "2 Sep 1992", "runtime" => 30, "rating" => 8.5, "summary" => "Suddenly Full-Throttle!! The Radiant Vegeta's Super PowerCell obliterates a chain of islands in search of Android 18! Vegeta, fresh from the time chamber, is ready to test his new strength against the monster, but is he really stronger than a Super Saiyan?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423772.jpg"),
        array("id" => "s5e17", "season" => 5, "number" => 17, "name" => "Bow to the Prince", "airdate" => "9 Sep 1992", "runtime" => 30, "rating" => 8.5, "summary" => "On Your Knees, Cell! I am Super Vegeta!!Vegeta shows cell his new power while Goku and Gohun train.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423773.jpg"),
