    array("number" => 8, "name" => "Season 8", "rating" => 8.5, "episodes" => array(
        array("id" => "s8e1", "season" => 8, "number" => 1, "name" => "The Wizard's Curse", "airdate" => "9 Mar 1994", "runtime" => 30, "rating" => 8.5, "summary" => "The Man Behind the Curtain Appears!! The Evil Mage BabidiThe Z-Fighters race to stop Babidi's cronies from delivering the pure energy that will be used resurrect the dreaded Majin Buu. Will they find Babidis hidden spaceship in time?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423447.jpg"),
        array("id" => "s8e2", "season" => 8, "number" => 2, "name" => "King of the Demons", "airdate" => "16 Mar 1994", "runtime" => 30, "rating" => 8.5, "summary" => "The Awaiting Trap!! A Challenge From the Demon RealmPiccolo and Krillin are turned to stone by Dabura! Determined to save their friends, Goku, Gohan, and Vegeta board Babidi's ship only to find themselves trapped! Can they save their friends and find their wa…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423448.jpg"),
        array("id" => "s8e3", "season" => 8, "number" => 3, "name" => "Vegeta Attacks", "airdate" => "23 Mar 1994", "runtime" => 30, "rating" => 8.5, "summary" => "Don't Toy With Me!! Vegeta Breaks Through the First Fight in a FuryAt each stage of Babidi's ship, Goku, Gohan, and Vegeta must face a fearsome warrior, each more powerful than the last. There's no room for error. Even the tiniest mistake will enable Babidi t…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423450.jpg"),
        array("id" => "s8e4", "season" => 8, "number" => 4, "name" => "Next Up, Goku", "airdate" => "13 Apr 1994", "runtime" => 30, "rating" => 8.5, "summary" => "Goku's Power Wide Open!! Blow Away YakonBabidi unleashes his monster Yakon to steal the Z-Fighters' energy for Majin Buu. The battle at Stage Two is sure to be intense, as Yakon is one of the most fearsome creatures in the universe!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423451.jpg"),
        array("id" => "s8e5", "season" => 8, "number" => 5, "name" => "Battle Supreme", "airdate" => "20 Apr 1994", "runtime" => 30, "rating" => 8.5, "summary" => "A Great Miscalculation!! Satan vs Three Super Warriors?!At the World Martial Arts Tournament, the five remaining competitors enter the ring for an all-out Battle Royale! The fists fly as Number 18, Mighty Mask, and Mr. Satan duke it out to decide who will be…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423452.jpg"),
        array("id" => "s8e6", "season" => 8, "number" => 6, "name" => "Eighteen Unmasks", "airdate" => "27 Apr 1994", "runtime" => 30, "rating" => 8.5, "summary" => "Such Strong Kids!! No. 18's Close Fight?!The battle heats up as Number 18 and Mighty Mask take their fight to the skies. Number 18 gives it everything she's got, but her attacks prove useless against her masked opponent. Could she find the edge she needs to w…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423453.jpg"),
        array("id" => "s8e7", "season" => 8, "number" => 7, "name" => "Pay to Win", "airdate" => "4 May 1994", "runtime" => 30, "rating" => 8.5, "summary" => "A Confrontation With the Demon King! It's Your Turn Gohan!!As the final bout of the tournament continues, Number 18 throws the defending champ for a loop by offering to throw the fight! Meanwhile, Babidi has selected his warrior for Stage 3: Dabura, King of t…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423455.jpg"),
        array("id" => "s8e8", "season" => 8, "number" => 8, "name" => "Heart of a Villain", "airdate" => "18 May 1994", "runtime" => 30, "rating" => 8.5, "summary" => "A Wicked Heart is Discovered!! Dabura's Good IdeaThe intense battle between Gohan and Dabura rages on, but just as the Stage 3 clash reaches a heated peak, Dabura stops the fight! Why has the evil giant conceded, and what is the great discovery he claims to h…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423456.jpg"),
        array("id" => "s8e9", "season" => 8, "number" => 9, "name" => "The Dark Prince Returns", "airdate" => "25 May 1994", "runtime" => 30, "rating" => 8.5, "summary" => "Vegeta, the Prince of Destruction, is Revived!! Intrusion at the TournamentIn an all-out assault against Vegeta, Babidi uses his power to undo the unsuspecting Prince from within! Vegeta is stripped of his good qualities by the wicked wizard, and becomes the…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423457.jpg"),
        array("id" => "s8e10", "season" => 8, "number" => 10, "name" => "Vegeta's Pride", "airdate" => "15 Jun 1994", "runtime" => 30, "rating" => 8, "summary" => "A Super Confrontation of Destiny!! The Clash of Goku vs VegetaGoku has no choice but to accept Vegeta's challenge.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423458.jpg"),
        array("id" => "s8e11", "season" => 8, "number" => 11, "name" => "The Long Awaited Fight", "airdate" => "22 Jun 1994", "runtime" => 30, "rating" => null, "summary" => "Just You Wait, Babidi!! Your Aspirations Will Not be AllowedThe battle between Goku and Vegeta has begun! With Babidi's magic enhancing his already incredible strength, Vegeta matches Goku move for move, but every blow the Saiyan Prince lands is a boost for M…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423460.jpg"),
        array("id" => "s8e12", "season" => 8, "number" => 12, "name" => "Magic Ball of Buu", "airdate" => "29 Jun 1994", "runtime" => 30, "rating" => null, "summary" => "The Seal is Broken! Out Comes the Vicious Majin Buu!!Gohan and the Supreme Kai confront Babidi in the depths of his space ship. With the fight between Goku and Vegeta supplying vast quantities of energy for Majin Buu, with not a moment to lose.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423464.jpg"),
        array("id" => "s8e13", "season" => 8, "number" => 13, "name" => "Buu is Hatched", "airdate" => "6 Jul 1994", "runtime" => 30, "rating" => null, "summary" => "I Won't Allow the Revival!! A Kamehameha of ResistanceThe seal encasing Buu is finally broken! Supreme Kai insists on retreat, but Gohan refuses, launching an incredible series of energy attacks. When the shell opens, nothing is inside! Gohan, however, there…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423468.jpg"),
        array("id" => "s8e14", "season" => 8, "number" => 14, "name" => "The Losses Begin", "airdate" => "13 Jul 1994", "runtime" => 30, "rating" => null, "summary" => "A Straight Line to Despair?! The Grief of KaiōshinWith his big pink belly and infantile behavior, Buu doesn't fit the bill of a galaxy destroyer - until he hurls Dabura into a cliff with a single blow! Gohan senses a limitless power, and the Supreme Kai insis…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/569/1423470.jpg"),
        array("id" => "s8e15", "season" => 8, "number" => 15, "name" => "The Terror of Majin Buu", "airdate" => "27 Jul 1994", "runtime" => 30, "rating" => null, "summary" => "Supreme Kai must use his unique fighting powers to keep Buu at bay - or lose his life! One mile away, Goten and Trunks stumble upon Piccolo, still frozen in stone, and accidentally shatter him to pieces! And there's more! The King of Demons returns!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435817.jpg"),
        array("id" => "s8e16", "season" => 8, "number" => 16, "name" => "Meal Time", "airdate" => "3 Aug 1994", "runtime" => 30, "rating" => null, "summary" => "Free from the grip of Babidi, Vegeta decides to seek his revenge by destroying the monster Majin Buu. Assuming Gohan to be a victim of the voracious villain, the Super Saiyan goes ballistic. Can Vegeta bring down Buu?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435816.jpg"),
        array("id" => "s8e17", "season" => 8, "number" => 17, "name" => "The Warrior's Decision", "airdate" => "17 Aug 1994", "runtime" => 30, "rating" => null, "summary" => "A Warrior's Resolution!! I Will Dispose of the MajinThe battle between Prince of Destruction Vegeta and Buu has begun! Vegeta is forced into a tough fight like never before as Buu shows no signs of taking any damage even after a hole is pierced in his stomach…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435604.jpg"),
        array("id" => "s8e18", "season" => 8, "number" => 18, "name" => "Final Atonement", "airdate" => "24 Aug 1994", "runtime" => 30, "rating" => null, "summary" => "For Those Whom He Loves… Vegeta Perishes!!After fighting with Majin Buu, Vegeta realizes he isn't fighting for just himself, but for the entire planet, and commits the ultimate sacrifice.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435600.jpg"),
        array("id" => "s8e19", "season" => 8, "number" => 19, "name" => "Evil Lives On", "airdate" => "31 Aug 1994", "runtime" => 30, "rating" => null, "summary" => "The Nightmare Revisited! Majin Buu has SurvivedMajin Buu's flesh is scattered on the battlefield, but his mystical power is rebuilding the monster into one deadly piece. Babidi is recovering, too, having narrowly survived Piccolo's attack.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435592.jpg"),
        array("id" => "s8e20", "season" => 8, "number" => 20, "name" => "Find the Dragonballs", "airdate" => "7 Sep 1994", "runtime" => 30, "rating" => null, "summary" => "The Struggle of Videl and the Others! Find the Dragon BallsVidel, Yamcha, Master Roshi, Chi Chi and Bulma find the last Dragon Ball... then it gets eaten by a dinosaur.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435591.jpg"),
        array("id" => "s8e21", "season" => 8, "number" => 21, "name" => "Revival", "airdate" => "21 Sep 1994", "runtime" => 30, "rating" => null, "summary" => "Enormous Hope!! A New Finishing Technique for the Little SquirtsGoku hatches a plan for defeating Majin Buu: Fusion! By joining two fighters of equal size and strength, an entirely new fighter can be created. But only one such pair remains-Goten and Trunks! C…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435589.jpg"),
        array("id" => "s8e22", "season" => 8, "number" => 22, "name" => "Global Announcement", "airdate" => "28 Sep 1994", "runtime" => 30, "rating" => null, "summary" => "Goten and Trunks — The World's Most WantedBabidi seeks vengeance against Piccolo, Goten, and Trunks! Plastering images on everyone's mind, Babidi threatens to terrorize humanity until the trio is brought forward! Meanwhile, Gohan is taken to Supreme Kai's wor…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435588.jpg"),
        array("id" => "s8e23", "season" => 8, "number" => 23, "name" => "Learn to Fuse!", "airdate" => "12 Oct 1994", "runtime" => 30, "rating" => null, "summary" => "Gohan is Revived — Kaiōshin's Secret Weapon?!Goku begins training Goten and Trunks in the art of Fusion. Meanwhile, Gohan, having been healed in Supreme Kai's world, tries to remove the legendary Z-Sword to use in the fight against Majin Buu!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435587.jpg"),
        array("id" => "s8e24", "season" => 8, "number" => 24, "name" => "The Z Sword", "airdate" => "19 Oct 1994", "runtime" => 30, "rating" => null, "summary" => "It Came Ou~t!! The Legendary Z SwordMajin Buu launches into a feeding frenzy, transforming an entire town's population into chocolate! Gohan draws the ancient Z-Sword, Goku struggles to teach Goten and Trunks the art of Fusion, and an unlikely hero is asked t…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435584.jpg"),
        array("id" => "s8e25", "season" => 8, "number" => 25, "name" => "Race to Capsule Corp.", "airdate" => "2 Nov 1994", "runtime" => 30, "rating" => null, "summary" => "West City is Targeted! Stop, Majin Buu!!As Goten and Trunks train to stop the vicious Majin Buu, Idasa's jaded mother tells Babidi exactly where Trunks lives! The Z-Fighters must now find a way to stop the evil wizard before he reaches Capsule Corp!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435581.jpg"),
        array("id" => "s8e26", "season" => 8, "number" => 26, "name" => "Super Saiyan 3", "airdate" => "9 Nov 1994", "runtime" => 30, "rating" => null, "summary" => "An Astounding, Great Transformation!! Super Saiyan 3Trunks searches frantically for the lost dragon radar, and Goku powers-up to an unimaginable level: Super Saiyan 3! Will this newfound strength be enough to stop Majin Buu from destroying West City?", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435570.jpg"),
        array("id" => "s8e27", "season" => 8, "number" => 27, "name" => "Buu's Mutiny", "airdate" => "16 Nov 1994", "runtime" => 30, "rating" => null, "summary" => "Bye-Bye, Babidi!! Majin Buu RebelsGoku uses his new Super Saiyan 3 abilities to combat the evil Majin Buu, buying Trunks the time he needs to locate the missing Dragon Radar. But now that Goku has started the fight, he may not be able to escape!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435569.jpg"),
        array("id" => "s8e28", "season" => 8, "number" => 28, "name" => "The Fusion Dance", "airdate" => "23 Nov 1994", "runtime" => 30, "rating" => null, "summary" => "Absurdly Awful Looking?! The Special Training Transformation PoseLiberated from his master, Majin Buu becomes even more destructive than before, wiping out entire cities in mere seconds! Earth's only hope now rests on the shoulders of two young warriors: Gote…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435568.jpg"),
        array("id" => "s8e29", "season" => 8, "number" => 29, "name" => "Goku's Time Is Up", "airdate" => "30 Nov 1994", "runtime" => 30, "rating" => null, "summary" => "See You Later, Everybody!! Goku Returns to the AfterlifeTensions rise for Goten and Trunks as their duel with Majin Buu approaches. Meanwhile, Buu prepares for the upcoming battle by building himself a home! Elsewhere, Goku bids a poignant farewell as he fina…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435567.jpg"),
        array("id" => "s8e30", "season" => 8, "number" => 30, "name" => "Return to Other World", "airdate" => "7 Dec 1994", "runtime" => 30, "rating" => null, "summary" => "Where is Gohan?! Training in the Kaiōshin RealmWhile Trunks and Goten continue their quest to perfect the Fusion Technique, Gohan seeks to master the Z-Sword. Back on Earth, an encounter with a blind boy reveals that there is another side to the belligerent B…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435566.jpg"),
        array("id" => "s8e31", "season" => 8, "number" => 31, "name" => "Out from the Broken Sword", "airdate" => "14 Dec 1994", "runtime" => 30, "rating" => null, "summary" => "You're Kidding, Right?! The Z Sword is BrokenGohan breaks the Z Sword in training, but from within it comes a new Kai, with a new technique!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435565.jpg"),
        array("id" => "s8e32", "season" => 8, "number" => 32, "name" => "Gotenks is Born", "airdate" => "21 Dec 1994", "runtime" => 30, "rating" => null, "summary" => "The Birth of a Superhuman Warrior!! His Name is GotenksAfter many comical misfires, Trunks and Goten finally perfect the Fusion technique, and Gotenks is born! Defying Piccolo's command, the super-kid immediately leaves to go fight Majin Buu! Is Gotenks ready…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435563.jpg"),
        array("id" => "s8e33", "season" => 8, "number" => 33, "name" => "Unlikely Friendship", "airdate" => "11 Jan 1995", "runtime" => 30, "rating" => null, "summary" => "The Final Weapon is Engaged?! Satan Will Save the EarthAs Majin Buu continues to terrorize humanity, a lone savior appears: Mr. Satan! But his Megaton punch won't be enough to stop the monster, but this unlikely hero may have a few surprises in store for Buu!", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435562.jpg"),
        array("id" => "s8e34", "season" => 8, "number" => 34, "name" => "I Kill No More", "airdate" => "25 Jan 1995", "runtime" => 30, "rating" => null, "summary" => "I've Stopped Killing!! Majin Buu's Good Boy DeclarationWhile the Z-Fighters continue training in preparation for their battle with Majin Buu, Mr. Satan devises some sneakier plans to take the villain down. But will he even need to carry them out? Is Majin Buu…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/574/1435561.jpg"),
    )),
    array("number" => 9, "name" => "Season 9", "rating" => null, "episodes" => array(
